sys_script.script:
(function executeRule(current, previous) {

    try {

        // Run validation only when Status changes to a non-Draft state
        if (!current.status.changes() || current.getValue('status') == 'draft')
            return;

        var participantAssignmentSysId = current.getUniqueValue();

        if (!participantAssignmentSysId)
            return;

        var missingMappings = [];

        // ============================================================
        // 1. GET ALL PLAN ASSIGNMENTS
        // ============================================================

        var planAssignmentGR = new GlideRecord('x_ctans_incentnow_plan_users');
        planAssignmentGR.addQuery('participant_assignment', participantAssignmentSysId);
        planAssignmentGR.query();

        // At least one Plan Assignment is mandatory
        if (!planAssignmentGR.hasNext()) {
            gs.addErrorMessage(
                'Participant Assignment cannot move out of Draft. ' +
                'At least one Plan Assignment must be added first.'
            );

            current.setAbortAction(true);
            return;
        }

        while (planAssignmentGR.next()) {

            var planAssignmentSysId = planAssignmentGR.getUniqueValue();
            var planSysId = planAssignmentGR.getValue('x_ctans_incentnow_plan');

            if (!planSysId)
                continue;

            var planDisplay = planAssignmentGR.getDisplayValue('x_ctans_incentnow_plan');

            // ========================================================
            // 2. GET ACTIVE QUOTA ATTAINMENT LOOKUP RULES
            // ========================================================

            var lookupGR = new GlideRecord('x_ctans_incentnow_lookup_rule');
            lookupGR.addQuery('plan', planSysId);
            lookupGR.addQuery('active', true);
            lookupGR.addQuery('rule_type', 'quota_attainment');
            lookupGR.query();

            while (lookupGR.next()) {

                var lookupRuleSysId = lookupGR.getUniqueValue();
                var lookupRuleDisplay = lookupGR.getDisplayValue();

                // ====================================================
                // 3. VERIFY LOOKUP RULE -> QUOTA MAPPING
                // ====================================================

                var quotaAssignmentGR = new GlideRecord('x_ctans_incentnow_user_quota_assignment');
                quotaAssignmentGR.addQuery('participant_assignment', participantAssignmentSysId);
                quotaAssignmentGR.addQuery('plan_assignment', planAssignmentSysId);
                quotaAssignmentGR.addQuery('lookup_rule', lookupRuleSysId);
                quotaAssignmentGR.addNotNullQuery('quota');
                quotaAssignmentGR.setLimit(1);
                quotaAssignmentGR.query();

                if (!quotaAssignmentGR.hasNext())
                    missingMappings.push(planDisplay + ' → ' + lookupRuleDisplay);
            }
        }

        // ============================================================
        // 4. BLOCK STATUS CHANGE IF ANY MAPPING IS MISSING
        // ============================================================

        if (missingMappings.length > 0) {

            gs.addErrorMessage(
                'Participant Assignment cannot move out of Draft. ' +
                'A Quota must be mapped to every applicable Quota Attainment Lookup Rule. ' +
                'Missing mappings: ' +
                missingMappings.join(', ')
            );

            current.setAbortAction(true);
        }

    } catch (e) {

        gs.error(
            '[IncentIQ Participant Assignment] Status validation failed. ' +
            'Participant Assignment=' +
            current.getUniqueValue() +
            ', Error=' +
            e.message
        );

        gs.addErrorMessage(
            'Participant Assignment status could not be changed because validation could not be completed.'
        );

        current.setAbortAction(true);
    }

})(current, previous);
